                new Choice("따뜻한 차를 대접한다", new Outcome("그녀는 차 한 잔에 의외로 감동합니다. \"다음엔 내가 대접하지.\"").P(PersonalStatId.Charity, 3).C(StatId.Authority, 3)))),
        CultEvent.Random("xg30", StatId.LeaderFaith, new Question("신이 된 뒤 처음 맞는 기념일, 천계의 오랜 연인(어느 신인지는 당신만 압니다)이 몰래 찾아옵니다. \"지상에 내려가더니 날 잊은 줄 알았어. 그 몸으로 나를 다시 기억해 줘.\"",
                new Choice("옛 연인을 그릇으로 맞이한다", 0.75f, new Outcome("천계에서 나누던 사랑이 처음으로 살과 피를 얻습니다. 익숙한 영혼과 낯선 육체 사이에서 두 사람은 밤새 서로를 다시 배웁니다. 새벽, 당신은 왜 신이 되었는지 기억해 냅니다.").P(PersonalStatId.Lust, 4).C(StatId.LeaderFaith, 8),
                    new Outcome("천계에 두 사람의 밀회가 들통났습니다. 연인을 시기하던 신들이 당신을 노립니다.").P(PersonalStatId.Lust, 2).X(GodEventEffect.Envy, 6)).With(PersonalStatId.Lust),
                new Choice("천계에서 다시 만나자고 약속한다", new Outcome("연인은 눈물을 훔치며 웃습니다. \"승천하면 그때 실컷.\"").P(PersonalStatId.Patience, 3).C(StatId.LeaderFaith, 3)))),
    };

    // 이 모드에서 뽑을 수 있는 성인 이벤트 (반복 등장하는 확률 이벤트)
    public static readonly CultEvent[] Normal = Shared.Concat(NormalOnly).ToArray();
    public static readonly CultEvent[] God = Shared.Concat(GodOnly).ToArray();
    public static readonly CultEvent[] All = Shared.Concat(NormalOnly).Concat(GodOnly).ToArray();

    public static CultEvent[] Pool(bool godMode) => godMode ? God : Normal;
}
